const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 86400000);
const twoWeeksAgo = new Date(now.getTime() - 14 * 86400000);
const rows = (n) => $(n).all().map((i) => i.json).filter((r) => Object.values(r).some((v) => norm(v) !== ''));
const leads = rows('Read Leads'); const content = rows('Read Content Drafts'); const feedback = rows('Read Feedback'); const waitlist = rows('Read Waitlist');
const inRange = (v, from, to) => { const d = new Date(norm(v)); return !Number.isNaN(d.getTime()) && d >= from && d < to; };
const leadDate = (l) => l.signup_date || l.first_contact || l.created_date;
const newLeadsThisWeek = leads.filter((l) => inRange(leadDate(l), weekAgo, new Date(now.getTime() + 1))).length;
const newLeadsPrevWeek = leads.filter((l) => inRange(leadDate(l), twoWeeksAgo, weekAgo)).length;
const leadsBySource = {};
leads.filter((l) => inRange(leadDate(l), weekAgo, new Date(now.getTime() + 1))).forEach((l) => { const s = norm(l.source) || 'unknown'; leadsBySource[s] = (leadsBySource[s] || 0) + 1; });
const st = (r) => norm(r.status).toLowerCase();
const contentThisWeek = content.filter((c) => inRange(c.created_date || c.approval_date, weekAgo, new Date(now.getTime() + 1))).length;
const ratings = feedback.map((f) => parseFloat(f.rating)).filter((r) => !Number.isNaN(r));
const avgRating = ratings.length ? (ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(1) : 'N/A';
const recCount = feedback.filter((f) => ['true', 'yes'].includes(norm(f.would_recommend).toLowerCase())).length;
const totalSignups = leads.filter((l) => ['active', 'converted'].includes(st(l))).length;
const wow = newLeadsPrevWeek > 0 ? (((newLeadsThisWeek - newLeadsPrevWeek) / newLeadsPrevWeek) * 100).toFixed(1) : (newLeadsThisWeek > 0 ? '100.0' : '0.0');
const referralLeads = leads.filter((l) => norm(l.source).toLowerCase() === 'referral');
return [{ json: {
  week_start: weekAgo.toISOString().slice(0, 10), week_end: now.toISOString().slice(0, 10),
  total_leads: leads.length, new_leads_this_week: newLeadsThisWeek, new_leads_prev_week: newLeadsPrevWeek, leads_by_source: leadsBySource,
  total_content_created: content.length, content_this_week: contentThisWeek,
  content_approved: content.filter((c) => st(c) === 'approved').length, content_pending: content.filter((c) => ['draft', 'pending'].includes(st(c))).length, content_published: content.filter((c) => st(c) === 'published').length,
  total_signups: totalSignups, conversion_rate: leads.length ? ((totalSignups / leads.length) * 100).toFixed(1) : '0.0',
  total_referrals: referralLeads.length, referrals_this_week: referralLeads.filter((l) => inRange(leadDate(l), weekAgo, new Date(now.getTime() + 1))).length,
  total_feedback: feedback.length, feedback_this_week: feedback.filter((f) => inRange(f.submitted_date || f.timestamp, weekAgo, new Date(now.getTime() + 1))).length,
  avg_feedback_rating: avgRating, nps_recommend_percent: feedback.length ? ((recCount / feedback.length) * 100).toFixed(0) : 'N/A',
  waitlist_size: waitlist.length, new_waitlist_this_week: waitlist.filter((x) => inRange(x.signup_date, weekAgo, new Date(now.getTime() + 1))).length,
  week_over_week_growth: wow, wow_trend: parseFloat(wow) > 0 ? 'up' : (parseFloat(wow) < 0 ? 'down' : 'flat'),
} }];

const norm = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const digits = (v) => norm(v).replace(/\D/g, '');
const yes = (v) => ['yes', 'true', '1', 'y'].includes(norm(v).toLowerCase());
const hoursSince = (iso) => { const t = Date.parse(norm(iso)); return Number.isNaN(t) ? Infinity : (Date.now() - t) / 3600000; };
const daysSince = (iso) => hoursSince(iso) / 24;
const nowIso = () => new Date().toISOString();
const appLink = () => norm($env.APP_DOWNLOAD_LINK);
const vendorLink = () => norm($env.APP_VENDOR_LINK) || appLink();
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const d = $input.first().json;
const sourceRows = Object.entries(d.leads_by_source || {}).map(([s, c]) => '<tr><td>' + esc(s) + '</td><td>' + c + '</td></tr>').join('') || '<tr><td colspan="2">No new leads this week</td></tr>';
const td = 'style="padding:8px;border-bottom:1px solid #eee;"';
const html = '<div style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;"><h1>Weekly Growth Report - Eki</h1><p>Week of ' + esc(d.week_start) + ' to ' + esc(d.week_end) + '</p>'
  + '<h2>Key metrics</h2><table style="width:100%;border-collapse:collapse;">'
  + '<tr><td ' + td + '>Total leads</td><td ' + td + '><b>' + d.total_leads + '</b></td></tr>'
  + '<tr><td ' + td + '>New leads this week</td><td ' + td + '><b>' + d.new_leads_this_week + '</b> (' + d.wow_trend + ' ' + d.week_over_week_growth + '% WoW)</td></tr>'
  + '<tr><td ' + td + '>Active signups</td><td ' + td + '><b>' + d.total_signups + '</b></td></tr>'
  + '<tr><td ' + td + '>Conversion rate</td><td ' + td + '><b>' + d.conversion_rate + '%</b></td></tr>'
  + '<tr><td ' + td + '>Waitlist size</td><td ' + td + '><b>' + d.waitlist_size + '</b> (+' + d.new_waitlist_this_week + ' new)</td></tr></table>'
  + '<h2>Leads by source</h2><table style="width:100%;border-collapse:collapse;">' + sourceRows + '</table>'
  + '<h2>Content</h2><p>Created this week: ' + d.content_this_week + ' | Approved: ' + d.content_approved + ' | Pending: ' + d.content_pending + ' | Published: ' + d.content_published + '</p>'
  + '<h2>Feedback</h2><p>Total: ' + d.total_feedback + ' (this week ' + d.feedback_this_week + ') | Average: ' + d.avg_feedback_rating + '/5 | Would recommend: ' + d.nps_recommend_percent + '%</p>'
  + '<h2>Referrals</h2><p>Total: ' + d.total_referrals + ' | This week: ' + d.referrals_this_week + '</p></div>';
const text = 'Weekly Growth Report\n' + d.week_start + ' -> ' + d.week_end + '\n\nNew leads: ' + d.new_leads_this_week + ' (' + d.wow_trend + ' ' + d.week_over_week_growth + '% WoW)\nTotal leads: ' + d.total_leads + '\nConversion: ' + d.conversion_rate + '%\nWaitlist: ' + d.waitlist_size + '\n\nContent: created ' + d.content_this_week + ', published ' + d.content_published + ', pending ' + d.content_pending + '\nFeedback: avg ' + d.avg_feedback_rating + '/5, recommend ' + d.nps_recommend_percent + '%\nReferrals this week: ' + d.referrals_this_week;
const to = norm($env.TEAM_EMAIL);
return [{ json: { ...d, telegram_text: text, send_email: !!(to && norm($env.RESEND_API_KEY) && norm($env.RESEND_FROM_EMAIL)), email_to: to, email_subject: 'Weekly Growth Report - ' + d.week_start + ' to ' + d.week_end, email_html: html } }];
